const raw = $input.first().json;
const payload = raw.body || raw;
const isEmptyPayload = !payload || Object.keys(payload).length === 0;

// Manual test runs have no payload - default to a sample competitor so the workflow is testable end to end
const triggerCompetitorDomain = payload.competitorDomain || (isEmptyPayload ? 'competitor-example.com' : null);
const triggerStartUrl = payload.startUrl || (isEmptyPayload && triggerCompetitorDomain ? 'https://' + triggerCompetitorDomain : null);

return [{
  json: {
    triggerCompetitorDomain: triggerCompetitorDomain || null,
    triggerStartUrl: triggerStartUrl || null,
    triggerMaxPages: Number(payload.maxPages) || null,
    triggerMaxDepth: Number(payload.maxDepth) || null,
    results: [],
    processedCompetitorCount: 0
  }
}];

const item = $input.first().json;
return [{
  json: {
    ...item,
    competitorQueue: [{
      competitorDomain: item.triggerCompetitorDomain,
      startUrl: item.triggerStartUrl || ('https://' + item.triggerCompetitorDomain),
      maxPages: item.triggerMaxPages || item.defaultMaxPagesPerCompetitor,
      maxDepth: item.triggerMaxDepth || item.defaultMaxDepthPerCompetitor
    }]
  }
}];

const state = $('IF - Ad Hoc Competitor Provided').first().json;
const response = $input.first().json;
const competitors = response.competitors || response.items || (Array.isArray(response) ? response : []);

const competitorQueue = competitors.map(c => {
  const domain = c.competitorDomain || c.domain || String(c);
  return {
    competitorDomain: domain,
    startUrl: c.startUrl || ('https://' + domain),
    maxPages: c.maxPages || state.defaultMaxPagesPerCompetitor,
    maxDepth: c.maxDepth || state.defaultMaxDepthPerCompetitor
  };
});

return [{
  json: {
    ...state,
    competitorQueue
  }
}];

const item = $input.first().json;
const competitorQueue = [...(item.competitorQueue || [])];
const next = competitorQueue.shift();

return [{
  json: {
    ...item,
    competitorQueue,
    currentCompetitorDomain: next ? next.competitorDomain : null,
    currentStartUrl: next ? next.startUrl : null,
    currentMaxPages: next ? next.maxPages : null,
    currentMaxDepth: next ? next.maxDepth : null,
    hasNextCompetitor: !!next,
    pageQueue: next ? [{ url: next.startUrl, depth: 0 }] : [],
    visitedPages: [],
    currentSitePages: [],
    pagesCrawledForCurrentCompetitor: 0
  }
}];

const item = $input.first().json;
const pageQueue = [...(item.pageQueue || [])];
const next = pageQueue.shift();

return [{
  json: {
    ...item,
    pageQueue,
    currentUrl: next ? next.url : null,
    currentDepth: next ? next.depth : null,
    hasNextPage: !!next
  }
}];

const state = $('Code 6 - Get Next Page From Queue').first().json;
const response = $input.first().json;

const html = String(response.data || response.body || '');
const statusCode = response.statusCode || response.status || null;

function extract(re, str) {
  const m = str.match(re);
  return m ? m[1].replace(/\s+/g, ' ').trim() : '';
}

const title = extract(/<title[^>]*>([\s\S]*?)<\/title>/i, html);
const canonical = extract(/<link[^>]+rel=["']canonical["'][^>]+href=["']([^"']*)["']/i, html);
const h1s = [...html.matchAll(/<h1[^>]*>([\s\S]*?)<\/h1>/gi)].map(m => m[1].replace(/<[^>]+>/g, '').trim());

const jsonLdBlocks = [...html.matchAll(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)].map(m => m[1]);
let schemaTypes = [];
for (const block of jsonLdBlocks) {
  try {
    const parsed = JSON.parse(block.trim());
    const items = Array.isArray(parsed) ? parsed : [parsed];
    for (const it of items) {
      if (it['@type']) schemaTypes.push(Array.isArray(it['@type']) ? it['@type'].join(',') : it['@type']);
      if (it['@graph']) {
        for (const g of it['@graph']) { if (g['@type']) schemaTypes.push(Array.isArray(g['@type']) ? g['@type'].join(',') : g['@type']); }
      }
    }
  } catch (e) { /* skip malformed JSON-LD */ }
}
schemaTypes = [...new Set(schemaTypes)];

const hrefs = [...html.matchAll(/<a[^>]+href=["']([^"'#]+)["'][^>]*>/gi)].map(m => m[1]);
const internalLinks = [];
for (const href of hrefs) {
  try {
    const resolved = new URL(href, state.currentUrl).href;
    if (new URL(resolved).host === state.currentCompetitorDomain) internalLinks.push(resolved);
  } catch (e) { /* skip malformed hrefs */ }
}

const textOnly = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
const wordCount = textOnly ? textOnly.split(' ').length : 0;

function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash * 31 + str.charCodeAt(i)) >>> 0;
  }
  return hash.toString(16);
}
const contentHash = simpleHash(textOnly);

return [{
  json: {
    ...state,
    statusCode,
    title,
    canonical,
    h1s,
    schemaTypes,
    internalLinks: [...new Set(internalLinks)],
    internalLinkCount: internalLinks.length,
    wordCount,
    contentHash
  }
}];

const item = $input.first().json;
const visitedPages = [...new Set([...(item.visitedPages || []), item.currentUrl])];
let pageQueue = [...(item.pageQueue || [])];

if ((item.currentDepth ?? 0) < item.currentMaxDepth) {
  const queuedUrls = new Set(pageQueue.map(q => q.url));
  for (const link of (item.internalLinks || [])) {
    const clean = link.split('#')[0];
    if (clean && !visitedPages.includes(clean) && !queuedUrls.has(clean)) {
      pageQueue.push({ url: clean, depth: (item.currentDepth ?? 0) + 1 });
      queuedUrls.add(clean);
    }
  }
}

const pageRecord = {
  url: item.currentUrl,
  title: item.title,
  canonical: item.canonical,
  h1s: item.h1s,
  schemaTypes: item.schemaTypes,
  internalLinkCount: item.internalLinkCount,
  wordCount: item.wordCount,
  contentHash: item.contentHash,
  statusCode: item.statusCode
};

return [{
  json: {
    ...item,
    visitedPages,
    pageQueue,
    currentSitePages: [...(item.currentSitePages || []), pageRecord],
    pagesCrawledForCurrentCompetitor: visitedPages.length
  }
}];

const state = $('IF - Page Queue Empty Or Page Budget Reached').first().json;
const response = $input.first().json;

const previousPages = response.pages || response.currentSitePages || (response.snapshot && response.snapshot.pages) || [];

const currentByUrl = {};
for (const p of state.currentSitePages) currentByUrl[p.url] = p;
const previousByUrl = {};
for (const p of previousPages) previousByUrl[p.url] = p;

const currentUrls = new Set(Object.keys(currentByUrl));
const previousUrls = new Set(Object.keys(previousByUrl));

let newPages = [...currentUrls].filter(u => !previousUrls.has(u)).map(u => currentByUrl[u]);
let removedPages = [...previousUrls].filter(u => !currentUrls.has(u)).map(u => previousByUrl[u]);

// URL migrations: a removed page whose content hash matches a new page's content hash
const urlMigrations = [];
const matchedNewUrls = new Set();
const matchedRemovedUrls = new Set();
for (const removed of removedPages) {
  const match = newPages.find(np => np.contentHash && removed.contentHash && np.contentHash === removed.contentHash && !matchedNewUrls.has(np.url));
  if (match) {
    urlMigrations.push({ from: removed.url, to: match.url, title: match.title });
    matchedNewUrls.add(match.url);
    matchedRemovedUrls.add(removed.url);
  }
}
newPages = newPages.filter(p => !matchedNewUrls.has(p.url));
const deletedPages = removedPages.filter(p => !matchedRemovedUrls.has(p.url));

// Group new pages into clusters by URL path prefix (first path segment)
const clusterMap = {};
for (const p of newPages) {
  let pathSegment = '/';
  try { pathSegment = '/' + (new URL(p.url).pathname.split('/').filter(Boolean)[0] || ''); } catch (e) { /* keep default */ }
  if (!clusterMap[pathSegment]) clusterMap[pathSegment] = [];
  clusterMap[pathSegment].push(p);
}
const newContentClusters = Object.entries(clusterMap)
  .filter(([, pages]) => pages.length >= 2)
  .map(([pathPrefix, pages]) => ({ pathPrefix, pageCount: pages.length, sampleTitles: pages.slice(0, 5).map(p => p.title) }));

const titleChanges = [];
const schemaChanges = [];
const internalLinkChanges = [];
const contentUpdates = [];
const internalLinkDeltaThreshold = state.internalLinkDeltaThreshold || 5;
const wordCountDeltaThreshold = state.wordCountDeltaThreshold || 100;

for (const url of currentUrls) {
  if (!previousUrls.has(url)) continue;
  const curr = currentByUrl[url];
  const prev = previousByUrl[url];

  if (curr.title !== prev.title) {
    titleChanges.push({ url, previousTitle: prev.title, currentTitle: curr.title });
  }

  const currSchema = (curr.schemaTypes || []).slice().sort().join(',');
  const prevSchema = (prev.schemaTypes || []).slice().sort().join(',');
  if (currSchema !== prevSchema) {
    schemaChanges.push({ url, previousSchema: prev.schemaTypes || [], currentSchema: curr.schemaTypes || [] });
  }

  const linkDelta = (curr.internalLinkCount || 0) - (prev.internalLinkCount || 0);
  if (Math.abs(linkDelta) >= internalLinkDeltaThreshold) {
    internalLinkChanges.push({ url, previousCount: prev.internalLinkCount, currentCount: curr.internalLinkCount, delta: linkDelta });
  }

  if (curr.contentHash !== prev.contentHash && curr.title === prev.title) {
    const wordCountDelta = (curr.wordCount || 0) - (prev.wordCount || 0);
    contentUpdates.push({ url, previousWordCount: prev.wordCount, currentWordCount: curr.wordCount, wordCountDelta });
  }
}

return [{
  json: {
    ...state,
    previousPages,
    hasPreviousSnapshot: previousPages.length > 0,
    newPages,
    deletedPages,
    urlMigrations,
    newContentClusters,
    titleChanges,
    schemaChanges,
    internalLinkChanges,
    contentUpdates
  }
}];

const aiResponse = $input.first().json;
const state = $('Code 9 - Diff Engine: Compute Site Changes').first().json;

let strategy;
try {
  const raw = aiResponse.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  strategy = JSON.parse(cleaned);
} catch (e) {
  strategy = { categoryInsights: {}, overallStrategyNarrative: 'Unable to parse AI response', confidence: 0, recommendedCounterActions: [] };
}

const changeCounts = {
  newContentClusters: (state.newContentClusters || []).length,
  deletedPages: (state.deletedPages || []).length,
  urlMigrations: (state.urlMigrations || []).length,
  titleChanges: (state.titleChanges || []).length,
  schemaChanges: (state.schemaChanges || []).length,
  internalLinkChanges: (state.internalLinkChanges || []).length,
  contentUpdates: (state.contentUpdates || []).length
};
const totalChanges = Object.values(changeCounts).reduce((a, b) => a + b, 0);
const significantStrategyChange = totalChanges >= (state.significantChangeCountThreshold || 5) && (strategy.confidence || 0) >= (state.strategyConfidenceThreshold || 60);

const competitorReport = {
  competitorDomain: state.currentCompetitorDomain,
  crawledAt: new Date().toISOString(),
  pagesCrawled: (state.currentSitePages || []).length,
  hasPreviousSnapshot: state.hasPreviousSnapshot,
  changeCounts,
  totalChanges,
  newContentClusters: state.newContentClusters,
  deletedPages: state.deletedPages,
  urlMigrations: state.urlMigrations,
  titleChanges: state.titleChanges,
  schemaChanges: state.schemaChanges,
  internalLinkChanges: state.internalLinkChanges,
  contentUpdates: state.contentUpdates,
  strategy,
  significantStrategyChange
};

return [{
  json: {
    ...state,
    strategy,
    significantStrategyChange,
    results: [...(state.results || []), competitorReport],
    processedCompetitorCount: (state.processedCompetitorCount || 0) + 1
  }
}];

