const item = $input.first().json;
const results = item.results || [];

const competitorsWithSignificantChange = results.filter(r => r.significantStrategyChange).length;

const categoryTotals = { newContentClusters: 0, deletedPages: 0, urlMigrations: 0, titleChanges: 0, schemaChanges: 0, internalLinkChanges: 0, contentUpdates: 0 };
for (const r of results) {
  for (const key of Object.keys(categoryTotals)) {
    categoryTotals[key] += (r.changeCounts && r.changeCounts[key]) || 0;
  }
}

return [{
  json: {
    whatsappBusinessPhoneId: item.whatsappBusinessPhoneId,
    whatsappRecipientPhone: item.whatsappRecipientPhone,
    competitorsChecked: results.length,
    competitorsWithSignificantChange,
    categoryTotals,
    competitorReports: results
  }
}];
